import { test } from "node:test";
import assert from "node:assert/strict";
import { shippingFee } from "../src/pricing.ts";

test("shipping is free at $50 or more", () => {
  assert.equal(shippingFee([{ sku: "a", price: 25, qty: 2 }]), 0);
  assert.equal(shippingFee([{ sku: "a", price: 30, qty: 2 }]), 0);
});

test("shipping below $50 is unchanged", () => {
  assert.equal(shippingFee([{ sku: "a", price: 49.99, qty: 1 }]), 5);
  assert.equal(shippingFee([]), 0);
});
